// Extrai o array de vagas retornado pela busca
const searchResponse = $input.first().json;
const jobs = searchResponse.jobs || [];

return jobs.map(job => ({
  json: {
    job_url: job.job_url,
    title: job.title,
    company: job.company,
    job_id: job.job_id
  }
}));

// Limpa a resposta da IA e converte para objeto JSON nativo
let inputText = $input.first().json.text;

try {
  let cleanText = inputText.replace(/```json/g, '').replace(/```/g, '').trim();
  let parsedJson = JSON.parse(cleanText);
  return [{ json: parsedJson }];
} catch (error) {
  return [{
    json: {
      error: "Falha ao converter resposta da IA em JSON",
      rawResponse: inputText
    }
  }];
}

